const entry  = msg.payload;
const source = msg.metadata.source;

// Skip entries older than last succesfull fetch
if (entry.timestamp <= source.timestamp) return null;

// Loop prevention — skip entries forwarded by the bridge
const callsigns = Object.values(msg.metadata.connection.clients).map(c => `[${c.client_system}]`);
if (callsigns.some(s => entry.author.includes(s))) return null;

// Skip parat-bridge system messages
if (entry.text && entry.text.startsWith("[parat-bridge]")) return null;


// Skip entries with a label matching the target identifier
if (entry.labels.some(l => l.id === msg.metadata.target.identifier)) return null;

msg.topic = "new_message"

return msg;
